document.body.className=localStorage.getItem('theme')||'';const _mutasiToken=new URLSearchParams(location.search).get('mutasi');const _isMutasiPath=location.pathname==='/mutasi'||location.pathname==='/mutasi/';if(_mutasiToken||_isMutasiPath){const tok=(_mutasiToken==='new'||_mutasiToken==='form')?'':(_mutasiToken||'');openMutasiLanding(tok);}else if(sessionStorage.getItem('activePortal')==='ado'&&typeof adoApi==='function'){adoApi('me').then(u=>startAdoSession(u)).catch(()=>login('ado'));}else{api('me').then(async x=>{me=x;if(admin()){try{const update=await api('system/update/status');if(update.busy||update.maintenance||sessionStorage.getItem('simonUpdateView')){view='Updates';sessionStorage.removeItem('simonUpdateView');}}catch{}}render()}).catch(()=>{if(!document.querySelector('#login'))login('simon');});}
let refreshingDashboard=false;
async function refreshDashboard(){
 if(refreshingDashboard||!me||document.hidden||document.querySelector('dialog[open]')||!['Devices','Overview'].includes(view))return;
 refreshingDashboard=true;const currentView=view,content=document.querySelector('#content'),currentUser=me;
 try{
  if(currentView==='Devices'){await filter(true);return}
  const [result,summary]=await Promise.all([api('devices?page=1&limit_=8&priority=true'),api(summaryPath())]);
  if(me!==currentUser||view!==currentView||!content?.isConnected||document.querySelector('dialog[open]'))return;
  devices=result.items;
  const tableContainer=content.querySelector('#overviewDevices');
  if(!tableContainer)return;
  applyNavSummary(summary);
  content.querySelectorAll('.kpi-card strong').forEach((node,index)=>{node.textContent=[summary.devices,summary.online,summary.offline,admin()?summary.unassigned:watchedStores(),summary.agent_old][index]});
  content.querySelector('#overviewCount').textContent=overviewCount(summary.devices);
  tableContainer.innerHTML=deviceTable(devices);
  tableContainer.querySelectorAll('[data-device]').forEach(button=>button.onclick=()=>details(button.dataset.device));
 }catch(error){console.warn('Pembaruan dashboard gagal:',error.message)}finally{refreshingDashboard=false}
}
setInterval(refreshDashboard,10000);
setInterval(refreshNavIndicators,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDashboard()});
window.addEventListener('focus',refreshDashboard);

async function backupDB(){const b=document.querySelector('#backupDB');b.disabled=true;try{const r=await fetch('/api/database/backup',{method:'POST',headers:{'X-SIAMS-Request':'1'}});if(r.status===401){login();return}if(!r.ok)throw Error((await r.json()).detail);const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=r.headers.get('Content-Disposition')?.match(/filename="?([^";]+)/)?.[1]||'simon-backup.db';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup database berhasil diunduh.')}catch(e){toast(e.message,'error')}finally{b.disabled=false}}

function passwordForm(){modal(`<h2>Ganti password</h2><form id="passwordEditor"><label>Password saat ini</label><input name="current_password" type="password" autocomplete="current-password" required><label>Password baru</label><input name="new_password" type="password" autocomplete="new-password" minlength="1" required><label>Ulangi password baru</label><input name="confirmation" type="password" autocomplete="new-password" required><p class="error" id="passwordError"></p><button>Simpan password</button></form>`);document.querySelector('#passwordEditor').onsubmit=async e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f)),error=f.querySelector('#passwordError');if(values.new_password!==values.confirmation){error.textContent='Konfirmasi password tidak sama';return}const button=f.querySelector('button');button.disabled=true;try{const result=await api('me/password',{current_password:values.current_password,new_password:values.new_password});login();document.querySelector('#err').textContent=result.message}catch(e){if(me)error.textContent=e.message}finally{button.disabled=false}}}

function monitoringSchedule(){return `<details class="monitoring-schedule"><summary>Jadwal pembaruan data</summary><div class="schedule-content"><dl><div><dt>Status koneksi</dt><dd>Sekitar 10 detik</dd></div><div><dt>CPU, RAM, dan kapasitas drive</dt><dd>Sekitar 10 detik</dd></div><div><dt>Suhu serta kondisi SSD</dt><dd>Mengikuti pembaruan XML Sentinel (sekitar 10 detik)</dd></div></dl><p><b>Refresh data</b> mengambil data terakhir yang sudah diterima server. Tombol ini tidak memerintahkan agent mengecek hardware saat itu juga. Jika belum ada kiriman baru, angka tetap sama.</p><small>Agent membaca perubahan XML Sentinel, tanpa menjalankan pemeriksaan SSD lewat PowerShell. Hanya kondisi disk terbaru dan riwayat alert penting yang disimpan. Status koneksi dan CPU/RAM memakai interval perkiraan; waktu kirim juga dipengaruhi koneksi jaringan. Daftar dashboard diperbarui otomatis setiap 10 detik saat terbuka; detail PC juga diperbarui otomatis sekitar 10 detik. Histori CPU/RAM disimpan per 5 menit untuk menjaga ukuran database.</small></div></details>`;}

// === SERVER STATUS & DATABASE MODAL ===
let serverStatus={ok:null,latency:null,dbKind:null,dbLabel:null,dbLatencyMs:null,pool:null,checkedAt:null};
async function fetchServerStatus(){try{const t0=Date.now();const r=await fetch('/api/health',{headers:{'X-SIAMS-Request':'1'}});const latency=Date.now()-t0;if(!r.ok){serverStatus={ok:false,latency,dbKind:null,dbLabel:null,dbLatencyMs:null,pool:null,checkedAt:Date.now()};paintServerStatus();return;}const d=await r.json();serverStatus={ok:true,latency,dbKind:d.database_kind,dbLabel:d.database_label||null,dbLatencyMs:d.db_latency_ms!=null?d.db_latency_ms:null,pool:d.pool||null,checkedAt:Date.now()};}catch(e){serverStatus={ok:false,latency:null,dbKind:null,dbLabel:null,dbLatencyMs:null,pool:null,checkedAt:Date.now()};}paintServerStatus();}
function _srvDotClass(ok,slow){if(ok===null)return 'server-dot-unknown';if(!ok)return 'server-dot-error';return slow?'server-dot-warn':'server-dot-ok';}
function _srvLatMs(){const{latency,dbLatencyMs}=serverStatus;return dbLatencyMs!=null?dbLatencyMs:latency;}
function paintServerStatus(){const sideDot=document.querySelector('.sidebar-server-dot');const sideLabel=document.querySelector('#sidebarServerStatus');const{ok,dbKind}=serverStatus;const isPostgres=String(dbKind||'').startsWith('postgresql');const dbName=isPostgres?'PostgreSQL':(dbKind||'—');const latMs=_srvLatMs();const slow=latMs!=null&&latMs>500;const dotClass=_srvDotClass(ok,slow);if(sideDot)sideDot.className='server-dot sidebar-server-dot '+dotClass;if(ok===null){if(sideLabel)sideLabel.textContent='Memeriksa...';}else if(!ok){if(sideLabel)sideLabel.textContent='Bermasalah!';}else{if(sideLabel)sideLabel.textContent=`${dbName}${latMs!=null?' · '+latMs+'ms':''}`;}}
function showServerStatusModal(){const{ok,dbKind,dbLabel,pool,checkedAt}=serverStatus;const isPostgres=String(dbKind||'').startsWith('postgresql');const dbName=isPostgres?'PostgreSQL':(dbKind||'Tidak diketahui');const latMs=_srvLatMs();const slow=latMs!=null&&latMs>500;const latLabel=latMs!=null?`${latMs} ms`:'—';const statusClass=_srvDotClass(ok,slow);const statusText=ok===null?'Memeriksa...':ok?(slow?'Lambat':'Normal'):'Error / Gangguan';const agoMs=checkedAt?Date.now()-checkedAt:null;const agoLabel=agoMs!=null?(agoMs<5000?'Baru saja':Math.round(agoMs/1000)+' detik lalu'):'—';const poolHtml=pool&&pool.pool_size!=null?`<div class="srv-stat-row"><span>Pool koneksi DB</span><b>${pool.checked_out??0} aktif / ${pool.pool_size} max${pool.overflow?` (+${pool.overflow} overflow)`:''}</b></div>`:'';const modalHtml=`<div class="card-heading" style="margin-bottom:12px"><div><h2 style="font-size:20px;margin:0 0 4px">Status Server &amp; Database</h2><p style="font-size:12px;margin:0;color:var(--muted)">Informasi real-time backend dan database SIMON.</p></div><span class="srv-status-badge ${statusClass}"><i></i>${esc(statusText)}</span></div><div class="srv-stat-grid"><div class="srv-stat-row"><span>Kondisi server</span><b>${ok?'Normal &amp; Terhubung':'Bermasalah'}</b></div><div class="srv-stat-row"><span>Jenis database</span><b>${esc(dbName)}</b></div>${dbLabel?`<div class="srv-stat-row"><span>Koneksi host</span><b class="srv-db-label">${esc(dbLabel)}</b></div>`:''}<div class="srv-stat-row"><span>Latensi database</span><b class="${slow?'srv-latency-warn':''}">${esc(latLabel)}</b></div>${poolHtml}<div class="srv-stat-row"><span>Terakhir diperiksa</span><b id="srvCheckedAgo">${esc(agoLabel)}</b></div></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:18px"><button id="refreshModalStatus" class="secondary compact">${uiIcon('check')} <span>Periksa ulang</span></button><button id="closeStatusModal" class="secondary compact">Tutup</button></div>`;const d=document.querySelector('#dialog');if(!d)return;d.classList.remove('device-dialog');d.innerHTML=modalHtml;d.showModal();d.querySelector('#closeStatusModal').onclick=()=>d.close();const refBtn=d.querySelector('#refreshModalStatus');if(refBtn){refBtn.onclick=async()=>{refBtn.disabled=true;const span=refBtn.querySelector('span');if(span)span.textContent='Memeriksa...';await fetchServerStatus();showServerStatusModal();};}}
const _origShell=shell;
shell=function(){_origShell();const sb=document.querySelector('.sidebar-bottom');if(sb){const dot=sb.querySelector('.server-dot');if(dot)dot.classList.add('sidebar-server-dot');const title=sb.querySelector('b');if(title&&!sb.querySelector('#sidebarServerStatus')){title.innerHTML=`Server: <span id="sidebarServerStatus">Memeriksa...</span>`;}sb.style.cursor='pointer';sb.title='Klik untuk melihat status server';sb.onclick=showServerStatusModal;}paintServerStatus();};
const _origRender=render;
render=async function(quiet=false){await _origRender(quiet);paintServerStatus();};
fetchServerStatus();
setInterval(fetchServerStatus,30000);
